const PropStep = struct { op: c_int, value: u32 = 0 };

fn run_prop_ops(cr: [*c]CharRange, steps: []const PropStep) c_int {
    var stack: [POP_STACK_LEN_MAX]CharRange = undefined;
    var stack_len: usize = 0;
    for (steps) |step| {
        switch (step.op) {
            POP_GC, POP_PROP, POP_CASE => {
                if (stack_len >= stack.len) return -1;
                cr_init(&stack[stack_len], cr.*.mem_opaque, cr.*.realloc_func);
                const status = switch (step.op) {
                    POP_GC => unicode_general_category1(&stack[stack_len], step.value),
                    POP_PROP => unicode_prop1(&stack[stack_len], @intCast(step.value)),
                    else => unicode_case1(&stack[stack_len], @intCast(step.value)),
                };
                if (status != 0) {
                    cr_free(&stack[stack_len]);
                    for (0..stack_len) |i| cr_free(&stack[i]);
                    return -1;
                }
                stack_len += 1;
            },
            POP_UNION, POP_INTER, POP_XOR => {
                if (stack_len < 2) return -1;
                var combined: CharRange = undefined;
                cr_init(&combined, cr.*.mem_opaque, cr.*.realloc_func);
                const range_op = step.op - POP_UNION + CR_OP_UNION;
                if (cr_op(&combined, stack[stack_len - 2].points, stack[stack_len - 2].len, stack[stack_len - 1].points, stack[stack_len - 1].len, range_op) != 0) {
                    cr_free(&combined);
                    for (0..stack_len) |i| cr_free(&stack[i]);
                    return -1;
                }
                cr_free(&stack[stack_len - 2]);
                cr_free(&stack[stack_len - 1]);
                stack[stack_len - 2] = combined;
                stack_len -= 1;
            },
            POP_INVERT => {
                if (stack_len == 0 or cr_invert(&stack[stack_len - 1]) != 0) {
                    for (0..stack_len) |i| cr_free(&stack[i]);
                    return -1;
                }
            },
            else => return -1,
        }
    }
    if (stack_len != 1) {
        for (0..stack_len) |i| cr_free(&stack[i]);
        return -1;
    }
    const status = cr_copy(cr, &stack[0]);
    cr_free(&stack[0]);
    return status;
}
