test "ASCII and Unicode case conversion" {
    var converted: [LRE_CC_RES_LEN_MAX]u32 = undefined;
    try @import("std").testing.expectEqual(@as(c_int, 1), lre_case_conv(&converted, 'a', 0));
    try @import("std").testing.expectEqual(@as(u32, 'A'), converted[0]);
    try @import("std").testing.expectEqual(@as(BOOL, TRUE), lre_is_id_start('A'));
    try @import("std").testing.expectEqual(@as(BOOL, TRUE), lre_is_id_start(0x03b1));
    try @import("std").testing.expectEqual(@as(u32, 'a'), @as(u32, @intCast(lre_canonicalize('A', TRUE))));
}

test "character ranges and Unicode property lookup" {
    var range: CharRange = undefined;
    cr_init(&range, null, null);
    defer cr_free(&range);
    try @import("std").testing.expectEqual(@as(c_int, 0), cr_union_interval(&range, 'a', 'z'));
    try @import("std").testing.expectEqual(@as(c_int, 0), unicode_general_category(&range, "Lu"));
    try @import("std").testing.expect(range.len >= 4);
}

test "script lookup and unknown-name result" {
    var range: CharRange = undefined;
    cr_init(&range, null, null);
    defer cr_free(&range);
    try @import("std").testing.expectEqual(@as(c_int, 0), unicode_script(&range, "Greek", FALSE));
    try @import("std").testing.expect(range.len > 0);
    range.len = 0;
    try @import("std").testing.expectEqual(@as(c_int, 0), unicode_script(&range, "Greek", TRUE));
    try @import("std").testing.expect(range.len > 0);
    range.len = 0;
    try @import("std").testing.expectEqual(@as(c_int, -2), unicode_script(&range, "NotAScript", FALSE));
}

fn sequence_counter(context: ?*anyopaque, codepoints: [*c]const u32, length: c_int) callconv(.c) void {
    _ = codepoints;
    _ = length;
    const count: *usize = @ptrCast(@alignCast(context.?));
    count.* += 1;
}

test "composite property and sequence callback" {
    var range: CharRange = undefined;
    cr_init(&range, null, null);
    defer cr_free(&range);
    try @import("std").testing.expectEqual(@as(c_int, 0), unicode_prop(&range, "Alphabetic"));
    var contains_a = false;
    for (0..@intCast(@divTrunc(range.len, 2))) |i| {
        if (range.points[i * 2] <= 'A' and 'A' < range.points[i * 2 + 1]) contains_a = true;
    }
    try @import("std").testing.expect(contains_a);

    range.len = 0;
    var sequence_count: usize = 0;
    try @import("std").testing.expectEqual(@as(c_int, 0), unicode_sequence_prop("Basic_Emoji", sequence_counter, @ptrCast(&sequence_count), &range));
    try @import("std").testing.expect(sequence_count > 0);
}

test "canonical normalization composes decomposed Latin" {
    const source = [_]u32{ 'e', 0x0301 };
    var output: [*c]u32 = null;
    const result_len = unicode_normalize(&output, &source, source.len, UNICODE_NFC, null, null);
    defer _ = realloc(@ptrCast(output), 0);
    try @import("std").testing.expectEqual(@as(c_int, 1), result_len);
    try @import("std").testing.expectEqual(@as(u32, 0x00e9), output[0]);
}
